/* file : CodeMapper.xml, id : getCodeMasterList */
SELECT A.*
, DATE_FORMAT(A.REG_DT, '%Y-%m-%d') AS REG_DT
FROM TB_CODE_MST A
WHERE A.DEL_YN = 'N'

	AND A.GRP_CD = #{grpCode}

ORDER BY GRP_CD
/*||ORDER BY GRP_CD||*/

/* file : CodeMapper.xml, id : getCodeDetailList */
SELECT A.*
	 , DATE_FORMAT(A.REG_DT, '%Y-%m-%d') AS REG_DT
FROM TB_CODE_DTL A
WHERE A.DEL_YN = 'N'
  AND A.GRP_CD = #{grpCd}
ORDER BY ORDBY
/*||ORDER BY ORDBY||*/

/* file : CodeMapper.xml, id : getCodeMaster */
  SELECT A.*
    FROM TB_CODE_MST A
   WHERE A.DEL_YN = 'N'
     AND A.GRP_CD = #{grpCd}

/* file : CodeMapper.xml, id : getCodeDetail */
SELECT A.*
FROM TB_CODE_DTL A
WHERE A.DEL_YN = 'N'
  AND A.GRP_CD = #{grpCd}
  AND A.DTL_CD     = #{dtlCd}

mapper.insert:
/* file : CodeMapper.xml, id : saveCodeMaster */
INSERT
  INTO TB_CODE_MST (
              GRP_CD
            , GRP_CD_NM
            , REG_USER_SEQ
            , REG_IP)
       VALUES (
              UPPER( #{grpCd} )
            , #{grpCdNm}
            , #{loginUserSeq}
            , #{loginUserIp})
    ON DUPLICATE KEY UPDATE GRP_CD_NM = #{grpCdNm}
     , DEL_YN                           = 'N'
     , MDFCN_USER_SEQ                       = #{loginUserSeq}
     , MDFCN_DT                           = CURRENT_TIMESTAMP
     , MDFCN_IP                             = #{loginUserIp}

/* file : CodeMapper.xml, id : saveCodeDetail */
INSERT
INTO TB_CODE_DTL (
				   GRP_CD
				 , DTL_CD
				 , DTL_CD_NM
				 , ORDBY
				 , USE_YN
				 , REG_USER_SEQ
				 , REG_IP)
VALUES (
		 UPPER( #{grpCd} )
	   , UPPER( #{dtlCd} )
	   , #{dtlCdNm}
	   , #{ordby}
	   , #{useYn}
	   , #{loginUserSeq}
	   , #{loginUserIp})
ON DUPLICATE KEY UPDATE DTL_CD_NM = #{dtlCdNm}
					  , ORDBY                          = #{ordby}
					  , USE_YN                       = #{useYn}
					  , DEL_YN                       = 'N'
					  , MDFCN_USER_SEQ                   = #{loginUserSeq}
					  , MDFCN_DT                       = CURRENT_TIMESTAMP
					  , MDFCN_IP                         = #{loginUserIp}

mapper.update:
/* file : CodeMapper.xml, id : deleteCodeMaster */
  UPDATE TB_CODE_MST
     SET DEL_YN     = 'Y'
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DT     = CURRENT_TIMESTAMP
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CD     = #{grpCd}

/* file : CodeMapper.xml, id : deleteCodeMasterDetail */
  UPDATE TB_CODE_DTL
     SET DEL_YN     = 'Y'
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DT     = CURRENT_TIMESTAMP
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CD     = #{grpCd}

/* file : CodeMapper.xml, id : deleteCodeDetail */
  UPDATE TB_CODE_DTL
     SET DEL_YN     = 'Y'
       , DEL_USER_SEQ = #{loginUserSeq}
       , DEL_DT     = CURRENT_TIMESTAMP
       , DEL_IP       = #{loginUserIp}
   WHERE GRP_CD     = #{grpCd}
     AND DTL_CD         = #{dtlCd}
